@ApiOperation("商户登录")
    @PostMapping(value = "{channelId}/login", produces = MediaType.APPLICATION_JSON_VALUE)
    public GenericResponse<MerchantTokenDTO> login(@PathVariable String channelId, @RequestBody MerchantLoginDTO merchantLoginDTO) {
        //渠道id放入threadlocal中
        ThreadLocalUtils.set(CHANNEL_ID, channelId);
        try {
            //登录校验
            MerchantTokenDTO merchantTokenDTO = merchantService.login(merchantLoginDTO);
            return GenericResponse.success(merchantTokenDTO);
        } finally {
            ThreadLocalUtils.remove();
        }
    }

@Override
    public MerchantTokenDTO login(MerchantLoginDTO merchantLoginDTO) {
        Preconditions.checkNotNull(merchantLoginDTO);
        Preconditions.checkNotNull(merchantLoginDTO.getAccountId());
        Preconditions.checkNotNull(merchantLoginDTO.getPassword());

        // 查询账户信息（邮箱登录）
        AccountVO accountVO = merchantAuthService.findByEmail(merchantLoginDTO.getAccountId());
        if (accountVO == null) {
            throw new TokenException(GawErrorCodeEnum.ERROR_WRONG_USER_OR_PASSWORD);
        }
        // 账户状态
        if (AccountStatusEnum.DISABLE.getCode().equals(accountVO.getStatus())){
            throw new TokenException(GawErrorCodeEnum.ERROR_LOGIN_RESULT_DISABLED);
        }

        // 调用登录接口
        LoginRespVo loginRespVo = externalMerchantService.login(accountVO.getEmail(), merchantLoginDTO.getPassword());

        if (isNull(loginRespVo)) {
            throw new TokenException(GawErrorCodeEnum.ERROR_WRONG_USER_OR_PASSWORD);
        }

        // 生成jwt
        Map<String, String> claims = Maps.newHashMap();
        //内部账号ID
        claims.put(TOKEN_CLAIM_ACCOUNTID, accountVO.getAccountId());
        //客户域返回的token
        claims.put(TOKEN_CLAIM_TOKEN, loginRespVo.getToken());
        //过期时间
        claims.put(TOKEN_CLAIM_EXPIREAT, String.valueOf(loginRespVo.getExpireAt()));
        //用户id
        claims.put(TOKEN_CLAIM_USERID, accountVO.getUserId());
        //渠道id
        String channelId = ThreadLocalUtils.get(CHANNEL_ID);
        claims.put(CHANNEL_ID, channelId);
        //生成jwt
        String jwt = JWTHelper.create(claims, new Date(loginRespVo.getExpireAt()));
        //是否是单点登录
        List<ServiceExtensionDO> serviceExtensionDOList= appRepository.findByServiceIdAndCode(Long.valueOf(channelId),MERCHANT_SSO_CHECK_KEY);
        //单点登录，将token放到redis处理
        if(CollectionUtils.isNotEmpty(serviceExtensionDOList)) {
            redisTemplate.opsForValue().set(CacheConstants.CACHE_NAME_USER_LOGIN_PREFIX + accountVO.getAccountId(), jwt, JWT_TOKEN_DEFAULT_EXPIRE, TimeUnit.SECONDS);
        }
        MerchantTokenDTO merchantTokenDTO = new MerchantTokenDTO();
        merchantTokenDTO.setToken(jwt);
        merchantTokenDTO.setExpireAt(loginRespVo.getExpireAt());
        return merchantTokenDTO;
    }

@Override
    public AccountVO findByEmail(String email) {
        if (isBlank(email)) {
            return null;
        }
        return authAssembler.toAccountVO(authRepository.findByEmail(email));
    }

public AccountE findByEmail(String email) {
        AuthAccountDO authAccountDO = authAccountDOMapper.selectByEmail(email);
        String phoneCallAccount = null;
        if (authAccountDO != null){
            phoneCallAccount = getPhoneCallAccount(authAccountDO.getAccountId().intValue());
        }
        return authConverter.toAccountE(authAccountDO, phoneCallAccount);
    }

public String getPhoneCallAccount(Integer accountId) {
        PhoneCallAccountPoolDO phoneCallAccountPoolDO = phoneCallAccountPoolDOMapper.selectByBindAccount(accountId);
        if (phoneCallAccountPoolDO == null) {
            return null;
        }
        return phoneCallAccountPoolDO.getPhoneCallAccount();
    }

public AccountVO toAccountVO(AccountE accountE) {
        if (accountE == null) {
            return null;
        }
        AccountVO accountVO = new AccountVO();
        accountVO.setAccountId(accountE.getAccountId().toString());
        accountVO.setUserId(accountE.getUserId());
        accountVO.setUserName(accountE.getUserName());
        accountVO.setCompany(accountE.getCompany());
        accountVO.setEmail(accountE.getEmail());
        accountVO.setPhone(accountE.getPhone());
        accountVO.setExtendInfo(accountE.getExtendInfo());
        accountVO.setStatus(accountE.getStatus());
        accountVO.setCreatorName(accountE.getCreatorName());
        accountVO.setModifierName(accountE.getModifierName());
        accountVO.setGmtModified(accountE.getGmtModified());
        accountVO.setPhoneCallAccount(accountE.getPhoneCallAccount());
        return accountVO;
    }

@RequestMapping(value = "/remove", method = {RequestMethod.GET})
    public String remove(@RequestParam(name = "id", required = false) Long id, @RequestParam(name = "name", required = false) String name) {
        if(id != null){
            rateLimiterService.remove(id);
        } else if (name != null) {
            rateLimiterService.remove(name);
        }
        return successMsg;
    }
